-- Administrative entities represented by the original local state.
CREATE TABLE subscriptions (environment_id VARCHAR(64) COLLATE utf8mb4_bin NOT NULL,id VARCHAR(64) COLLATE utf8mb4_bin NOT NULL,project_id VARCHAR(64) COLLATE utf8mb4_bin NOT NULL,plan_id VARCHAR(64) COLLATE utf8mb4_bin NOT NULL,customer_id VARCHAR(64) COLLATE utf8mb4_bin NOT NULL,status VARCHAR(20) NOT NULL,start_date DATE NOT NULL,next_renewal DATE NULL,cancel_date DATE NULL,external_id VARCHAR(255) NULL,row_version BIGINT UNSIGNED NOT NULL DEFAULT 1,archived_at DATETIME(6) NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(environment_id,id),UNIQUE(environment_id,external_id),FOREIGN KEY(environment_id) REFERENCES environments(id) ON DELETE RESTRICT,FOREIGN KEY(environment_id,project_id) REFERENCES projects(environment_id,id) ON DELETE RESTRICT,FOREIGN KEY(environment_id,plan_id) REFERENCES plans(environment_id,id) ON DELETE RESTRICT,FOREIGN KEY(environment_id,customer_id) REFERENCES customers(environment_id,id) ON DELETE RESTRICT,CONSTRAINT subscription_status CHECK(status IN ('activa','prueba','impaga','cancelada','pausada')),CONSTRAINT subscription_dates CHECK(cancel_date IS NULL OR cancel_date>=start_date),CONSTRAINT subscription_version CHECK(row_version>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE subscription_events (environment_id VARCHAR(64) COLLATE utf8mb4_bin NOT NULL,id VARCHAR(64) COLLATE utf8mb4_bin NOT NULL,subscription_id VARCHAR(64) COLLATE utf8mb4_bin NOT NULL,event_date DATE NOT NULL,event_type VARCHAR(24) NOT NULL,plan_id VARCHAR(64) COLLATE utf8mb4_bin NULL,amount DECIMAL(20,2) NULL,currency_id VARCHAR(64) COLLATE utf8mb4_bin NULL,sale_id VARCHAR(64) COLLATE utf8mb4_bin NULL,note VARCHAR(255) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(environment_id,id),FOREIGN KEY(environment_id,subscription_id) REFERENCES subscriptions(environment_id,id) ON DELETE RESTRICT,FOREIGN KEY(environment_id,plan_id) REFERENCES plans(environment_id,id) ON DELETE RESTRICT,FOREIGN KEY(environment_id,currency_id) REFERENCES currencies(environment_id,id) ON DELETE RESTRICT,CONSTRAINT subscription_event_type CHECK(event_type IN ('alta','prueba','conversion','renovacion','pago_fallido','cancelacion','cambio_plan','reactivacion','pausa')),CONSTRAINT subscription_event_amount CHECK(amount IS NULL OR amount>=0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE time_logs (environment_id VARCHAR(64) COLLATE utf8mb4_bin NOT NULL,id VARCHAR(64) COLLATE utf8mb4_bin NOT NULL,project_id VARCHAR(64) COLLATE utf8mb4_bin NOT NULL,logged_on DATE NOT NULL,hours DECIMAL(8,2) NOT NULL,kind VARCHAR(24) NOT NULL,note VARCHAR(255) NOT NULL,row_version BIGINT UNSIGNED NOT NULL DEFAULT 1,archived_at DATETIME(6) NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(environment_id,id),FOREIGN KEY(environment_id,project_id) REFERENCES projects(environment_id,id) ON DELETE RESTRICT,CONSTRAINT time_hours CHECK(hours>0 AND hours<=24),CONSTRAINT time_kind CHECK(kind IN ('desarrollo','mantenimiento','contenido','soporte')),CONSTRAINT time_version CHECK(row_version>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE integrations (environment_id VARCHAR(64) COLLATE utf8mb4_bin NOT NULL,id VARCHAR(64) COLLATE utf8mb4_bin NOT NULL,name VARCHAR(160) NOT NULL,kind VARCHAR(32) NOT NULL,method VARCHAR(32) NOT NULL,status VARCHAR(24) NOT NULL,project_id VARCHAR(64) COLLATE utf8mb4_bin NULL,last_sync DATETIME(6) NULL,errors_json JSON NOT NULL,notes TEXT NOT NULL,row_version BIGINT UNSIGNED NOT NULL DEFAULT 1,archived_at DATETIME(6) NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(environment_id,id),UNIQUE(environment_id,name),FOREIGN KEY(environment_id,project_id) REFERENCES projects(environment_id,id) ON DELETE RESTRICT,CONSTRAINT integration_status CHECK(status IN ('activa','error','pausada','sin_conectar')),CONSTRAINT integration_version CHECK(row_version>0),CONSTRAINT integration_errors CHECK(JSON_VALID(errors_json))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE suppliers (environment_id VARCHAR(64) COLLATE utf8mb4_bin NOT NULL,id VARCHAR(64) COLLATE utf8mb4_bin NOT NULL,name VARCHAR(160) NOT NULL,kind VARCHAR(120) NOT NULL,url VARCHAR(2048) NOT NULL,contact VARCHAR(255) NOT NULL,tax_id VARCHAR(120) NOT NULL,notes TEXT NOT NULL,row_version BIGINT UNSIGNED NOT NULL DEFAULT 1,archived_at DATETIME(6) NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(environment_id,id),UNIQUE(environment_id,name),FOREIGN KEY(environment_id) REFERENCES environments(id) ON DELETE RESTRICT,CONSTRAINT supplier_version CHECK(row_version>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
